<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Application\Service\Visibility\UserRoleAssignmentVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\UserRoleAssignment;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway\UserRoleAssignmentWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignmentCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignmentVisibilityService $visibility,
        private readonly UserRoleAssignmentWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for User role assignment");
        $span = $this->startSpan("Check allow of create usecase for User role assignment");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignmentCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(UserRoleAssignmentCreateParams $params): UserRoleAssignmentCreateResult
    {
        $this->logDebug("Run create usecase for User role assignment");
        $span = $this->startSpan("Run create usecase for User role assignment");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create User role assignment');
            }
            $this->dispatcher->dispatch(new UserRoleAssignmentCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new UserRoleAssignmentCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = UserRoleAssignment::create($input);
            $result = $this->writer->create(
                $entity,
                fn (UserRoleAssignment $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserRoleAssignmentCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
